import json
r=json.load(open("results/r1_analyses.json",encoding="utf-8")); e=json.load(open("results/exploratory_posthoc.json"))
L=[]
a=r["agreement"]; L.append(f"[Agreement, secondary labels recovered by re-query with max_tokens=120: {a['n_secondary_recovered']} of 86; n_both={a['n_both']}] weighted kappa={a['kappa_w']:.3f} (95% bootstrap CI {a['kappa_w_ci'][0]:.3f}-{a['kappa_w_ci'][1]:.3f}); unweighted kappa={a['kappa_unw']:.3f}; weighted positive agreement={a['pos_agreement_w']:.3f}, negative agreement={a['neg_agreement_w']:.3f}; kappa ENG={a['kappa_w_ENG']:.3f}, nonENG={a['kappa_w_nonENG']:.3f}; remaining missing secondary by stratum {a['secondary_missing_by_stratum']}")
L.append("[C/D primary positives with secondary/adjudicator(deepseek-chat-v3.1)/majority] " + "; ".join(f"{c['pub']} {c['stratum']} {c['lang']} sec={c['secondary']} adj={c['adjudicator']} maj={c['majority']}: {c['text'][:90]}" for c in r["CD_positives"]))
for k in ["primary_realized_pi","majority_reference"]:
    x=r[k]; L.append(f"[{k}] n_pos={x['n_pos']}; M1 F1={x['M1']['f1']:.3f} recall={x['M1']['recall']:.3f}; M2 F1={x['M2']['f1']:.3f} (CI {x['M2']['f1_ci'][0]:.3f}-{x['M2']['f1_ci'][1]:.3f}) recall={x['M2']['recall']:.3f}; H1 diff={x['H1_diff']:.3f} CI {x['H1_ci'][0]:.3f}..{x['H1_ci'][1]:.3f}; HT={x['HT']:.4f} (SE {x['HT_se_boot']:.4f}); DSL={x['DSL']:.4f} CI {x['DSL_ci'][0]:.4f}-{x['DSL_ci'][1]:.4f} (SE {x['DSL_se_boot']:.4f}); H3 diff={x['H3_diff']:.4f} CI {x['H3_ci'][0]:.4f}-{x['H3_ci'][1]:.4f}; DSL-LPM beta={x['DSL_beta']:.3f} sandwich SE={x['DSL_se']:.3f}; cond(A)={x['cond_A']:.3g}" + (f"; bootstrap CI of beta {x['DSL_beta_boot_ci'][0]:.2f}..{x['DSL_beta_boot_ci'][1]:.2f}" if 'DSL_beta_boot_ci' in x else ""))
L.append("[LOO of each C/D positive, primary] " + "; ".join(f"{l['pub']}({l['stratum']}): DSL {l['DSL_without']:.4f}, H3 {l['H3_without']:.4f}, M1 recall {l['M1_recall_without']:.3f}" for l in r["loo_CD_positives"]))
s=r["dsl_simulation"]; L.append(f"[DSL-LPM simulation, 200 reps, true beta 0.10, miscalibrated predictor] mean beta={s['mean_beta']:.3f}, median={s['median_beta']:.3f}, 95% sandwich coverage={s['coverage_95']:.2f}, mean SE={s['mean_se']:.2f}")
L.append(f"[Regression sample flow] {r['regression_flow']}")
L.append(f"[Post hoc unweighted M5u] F1@0.5={e['metrics']['M5u@0.5']['f1']:.3f}, F1@cv={e['metrics']['M5u@cv']['f1']:.3f}, recall_eng={e['metrics']['M5u@cv']['recall_eng']:.3f}, recall_noneng={e['metrics']['M5u@cv']['recall_noneng']:.3f}; DSL prevalence with M5u g={e['prevalence_dsl_g_M5u']['est']:.4f} CI {e['prevalence_dsl_g_M5u']['ci'][0]:.4f}-{e['prevalence_dsl_g_M5u']['ci'][1]:.4f}; DSL-LPM with M5u beta={e['H4_DSL_g_M5u']['beta']:.3f} SE={e['H4_DSL_g_M5u']['se']:.3f}")
open("results/r1_digest.txt","w",encoding="utf-8").write("\n".join(L)); print("\n".join(L))
